// Exact embedded pictograms avoid OCR and scaling errors in POLYPOINT PDF exports.
export function imagePlacements(ops,OPS,Util,viewport){let matrix=[1,0,0,1,0,0];const stack=[],images=[];const add=(id,m)=>{const t=Util.transform(viewport.transform,m);const points=[[0,0],[1,0],[0,1],[1,1]].map(([x,y])=>[t[0]*x+t[2]*y+t[4],t[1]*x+t[3]*y+t[5]]);const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);const x=Math.min(...xs),y=Math.min(...ys),w=Math.max(...xs)-x,h=Math.max(...ys)-y;if(w>2&&h>2&&w/h>.18&&w/h<2)images.push({id,x,y,w,h})};for(let i=0;i<ops.fnArray.length;i++){const fn=ops.fnArray[i],a=ops.argsArray[i];if(fn===OPS.save)stack.push([...matrix]);else if(fn===OPS.restore)matrix=stack.pop()||[1,0,0,1,0,0];else if(fn===OPS.transform)matrix=Util.transform(matrix,a);else if(fn===OPS.paintImageXObject)add(a[0],matrix);else if(fn===OPS.paintImageXObjectRepeat){const[id,sx,sy,positions]=a;for(let k=0;k<positions.length;k+=2)add(id,Util.transform(matrix,[sx,0,0,sy,positions[k],positions[k+1]]))}}return images}
export function imagesAtCell(placements,rect,day,days){
 const step=rect.w/days,x=rect.x+(day-.5)*step,y=rect.y+rect.h/2;
 const found=placements.filter(p=>Math.abs(p.x+p.w/2-x)<step*.49&&Math.abs(p.y+p.h/2-y)<rect.h*.4&&p.w<=step*1.15).sort((a,b)=>a.x-b.x||a.y-b.y);
 return found.filter((p,i)=>!found.slice(0,i).some(q=>Math.abs(q.x-p.x)<.1&&Math.abs(q.y-p.y)<.1&&Math.abs(q.w-p.w)<.1&&Math.abs(q.h-p.h)<.1));
}
export function imageAtCell(placements,rect,day,days){const x=rect.x+(day-.5)*rect.w/days,y=rect.y+rect.h/2;return placements.filter(p=>Math.abs(p.x+p.w/2-x)<rect.w/days*.4&&Math.abs(p.y+p.h/2-y)<rect.h*.4).sort((a,b)=>Math.abs(a.x+a.w/2-x)+Math.abs(a.y+a.h/2-y)-Math.abs(b.x+b.w/2-x)-Math.abs(b.y+b.h/2-y))[0]||null}
export function pixelRGBA(image){const {width,height,data,kind}=image;const rgba=new Uint8ClampedArray(width*height*4);if(kind===3){rgba.set(data);return rgba}if(kind===2){for(let i=0,j=0;i<data.length;i+=3,j+=4){rgba[j]=data[i];rgba[j+1]=data[i+1];rgba[j+2]=data[i+2];rgba[j+3]=255}return rgba}if(kind===1){const stride=Math.ceil(width/8);for(let y=0;y<height;y++)for(let x=0;x<width;x++){const c=(data[y*stride+(x>>3)]&(128>>(x&7)))?255:0;const j=(y*width+x)*4;rgba[j]=rgba[j+1]=rgba[j+2]=c;rgba[j+3]=255}return rgba}throw new Error('Nicht unterstütztes PDF-Bildformat.')}
